def _now_ms() -> float:
    """Returns a monotonic timestamp in milliseconds."""
    return monotonic() * 1000.0


def _now_iso() -> str:
    """Returns the current wall-clock time as an ISO 8601 timestamp."""
    return datetime.now(timezone.utc).isoformat()


