    per query at ``<log_dir>/<query_id>/events.jsonl``.
    """

    _closed: bool
    _query_starts: dict[str, float]
    _optimization_starts: dict[str, float]
    _exec_starts: dict[str, float]
    _operator_starts: dict[tuple[str, int], float]

    def __init__(self, log_dir: str | Path) -> None:
