        self._files: dict[str, TextIO] = {}

    def _write(self, query_id: str, event: str, **fields: Any) -> None:
        """Writes a single event line to the query's log file, if open."""
        handle = self._files.get(query_id)
        if handle is None:
            return
        record: dict[str, Any] = {"event": event, "ts": _now_iso(), "query_id": query_id}
        record.update(fields)
        handle.write(json.dumps(record, default=str) + "\n")
        handle.flush()

    def on_query_start(self, query_id: str, metadata: PyQueryMetadata) -> None:
        if self._closed:
            return

        query_dir = self._log_dir / query_id
        query_dir.mkdir(parents=True, exist_ok=True)
        self._files[query_id] = open(query_dir / "events.jsonl", "a")

        self._query_starts[query_id] = _now_ms()

        try:
            unoptimized_plan = metadata.unoptimized_plan
        except Exception:
            unoptimized_plan = None
        try:
            runner = metadata.runner
        except Exception:
            runner = None
        try:
            entrypoint = metadata.entrypoint
        except Exception:
            entrypoint = None

        self._write(query_id, "event_log_started")
        self._write(query_id, "query_started", runner=runner, entrypoint=entrypoint)
        self._write(query_id, "plan_unoptimized", plan=unoptimized_plan)

    def on_query_end(self, query_id: str, result: PyQueryResult) -> None:
        if self._closed:
            return

        start = self._query_starts.get(query_id)
        duration_ms = int(max(0.0, _now_ms() - start)) if start is not None else 0

        try:
            error_message = result.error_message
        except Exception:
            error_message = None

        self._write(
