        start = self._optimization_starts.get(query_id)
        duration_ms = int(max(0.0, _now_ms() - start)) if start is not None else None
        self._write(query_id, "plan_optimized", plan=optimized_plan, duration_ms=duration_ms)

    def on_exec_start(self, query_id: str, physical_plan: str) -> None:
